async function run() {
  const w = await http.getJSON("https://api.open-meteo.com/v1/forecast?latitude=" + params.cidade.latitude + "&longitude=" + params.cidade.longitude + "&daily=precipitation_probability_max,precipitation_sum&timezone=auto&forecast_days=2");
  const d = w && w.daily;
  if (!d || !d.precipitation_probability_max || d.precipitation_probability_max.length < 2 || d.precipitation_probability_max[1] === null) {
    log("Previsão de amanhã indisponível.");
    return;
  }
  const chance = d.precipitation_probability_max[1];
  if (chance < params.limite) {
    log("Amanhã: " + chance + "% de chuva, abaixo de " + params.limite + "%.");
    return;
  }
  let text = "☔ Amanhã em " + params.cidade.name + ": " + chance + "% de chance de chuva";
  const mm = d.precipitation_sum ? d.precipitation_sum[1] : null;
  if (typeof mm === "number" && mm > 0) text += ", cerca de " + (Math.round(mm * 10) / 10).toString().replace(".", ",") + " mm";
  text += ". Leve guarda-chuva!";
  await notify.send({text});
}
